{
  "PROP-6a4369e9-pre-008": {
    "property_id": "PROP-6a4369e9-pre-008",
    "audit_result": {
      "property_id": "PROP-6a4369e9-pre-008",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/rpc_data_column_sidecars_by_range.go::dataColumnSidecarsByRangeRPCHandler::L72-74",
      "proof_trace": "When requests fall outside data_column_serve_range, validateDataColumnsByRange returns nil (L198-200), causing the handler to return nil (L72-74) which sends a success response with zero sidecars instead of responseCodeResourceUnavailable as required by the assertion.",
      "attack_scenario": "Attacker sends DataColumnSidecarsByRangeRequest with startSlot before minValidSlot or after currentSlot. Server responds with success (code 0x00) and empty data instead of ResourceUnavailable (code 0x03), violating P2P spec expectations.",
      "checklist_id": "PROP-6a4369e9-pre-008"
    },
    "text": "data_column_sidecars_by_range must reject requests outside data_column_serve_range.",
    "assertion": "forall req: req.range outside serve_range => response == ResourceUnavailable",
    "covers": "SG-008",
    "severity": "MEDIUM",
    "type": "pre-condition"
  }
}

